/usr/bin/bash -lc "python - <<'PY'
import pathlib,re,collections,yaml
p=pathlib.Path('candidate/statement-ledger.md'); lines=p.read_text().splitlines(); claims=yaml.safe_load(pathlib.Path('lean/claims.yaml').read_text()); print('CLAIMS ROOT',type(claims).__name__,list(claims) if isinstance(claims,dict) else len(claims))
rows=[]; section=''; counts=collections.Counter(); kinds=collections.Counter(); declared=[]
for i,l in enumerate(lines,1):
 if l.startswith('## '): section=l[3:]
 if l.startswith('| ') and section not in ('Index by label','Scope'):
  ds=re.findall(r'"'`(StratonovichHAM(?:Audit|SecondMoment)'"\\.["'^`]+)`'"',l)
  for d in ds: rows.append((d,i,l.split('|')[1].strip(),section));counts[section]+=1
print('ROWS',len(rows),'labelled',sum(not x[2].startswith('no direct label') for x in rows),'unlabelled',sum(x[2].startswith('no direct label') for x in rows)); print('PER-MODULE',dict(counts)); print('DUP ROWS',[(d,c) for d,c in collections.Counter(r[0] for r in rows).items() if c"'!=1])
cs=claims['"'claims'] if isinstance(claims,dict) else claims
cc=collections.Counter(c['decl'] for c in cs); rc=collections.Counter(r[0] for r in rows); print('CLAIMS',len(cs),'kinds',dict(collections.Counter(c['kind'] for c in cs))); print('MISSING/EXTRA',list((cc-rc).items()),list((rc-cc).items()))
for c in cs:
 if 'UniformSeriesTail.' in c['decl']:
  d=c['decl'].replace('StratonovichHAMSecondMoment.',''); print('INDEX',d,[(i,l.split('|')[1].strip()) for i,l in enumerate(lines,1) if 281<=i<=542 and '"'`'"'+d+'"'`'"' in l])
co=yaml.safe_load(pathlib.Path('lean/coverage.yaml').read_text()); ds=yaml.safe_load(pathlib.Path('docs/coverage-scope-tex.yaml').read_text()); cov={r['paper']['label']:r for r in co['rows']};print('COVERAGE CLASSES',dict(collections.Counter(r['class'] for r in co['rows']))); print('DOC ASCII',[(r['label'],r['ascii']==cov[r['label']]['conclusion_scope']) for r in ds['rows']]);
labels=collections.defaultdict(list)
for f in pathlib.Path('manuscript/notes').rglob('*.tex'):
 for i,l in enumerate(f.read_text().splitlines(),1):
  for lab in re.findall(r'\\\\label\\{(["'^}]+)'"\\}',l): labels[lab].append((str(f),i))
for lab in ['L:uniform-series-tail','E:uniform-series-tail','L:terminal-wick','E:terminal-term-majorant','E:terminal-wick-formula']:
 print('LABEL',lab,labels[lab])
PY"

